<?php
declare(strict_types=1);
require_once __DIR__.'/payments.php';
function lc_flow_installed():bool{return crm_query("SELECT state FROM nd_schema_migrations WHERE version='016_order_lifecycle'")->fetchColumn()==='applied';}
function lc_flow(array $a,int $id,bool $lock=false):array{$f=crm_query('SELECT * FROM nd_lc_order_flow WHERE order_id=?'.($lock?' FOR UPDATE':''),[$id])->fetch();if(!$f)crm_fail(404,'Цикл заказа не найден.');cc_project($a,(int)$f['project_id']);return $f;}
function lc_flow_active(array $f):void{if($f['case_state']!=='ACTIVE')crm_fail(409,'Заказ приостановлен, закрыт или требует решения спора. История и чеки доступны для чтения.');}
function lc_flow_save(array $a,array $f,string $action,array $values,array $evidence):array{
 $allowed=['commercial_state','delivery_state','acceptance_state','case_state','brief_revision_id','quotation_id','proposal_binding_id','agreement_binding_id','final_manifest','final_hash','handover_hash','support_terms','support_start','support_end'];if(array_diff(array_keys($values),$allowed))throw new LogicException('unsupported_flow_field');$sets=[];$params=[];foreach($values as $key=>$v){$sets[]=$key.'=?';$params[]=$v;}$params[]=$f['order_id'];crm_query('UPDATE nd_lc_order_flow SET '.implode(',',$sets).',version=version+1 WHERE order_id=?',$params);lc_audit($a,'order',(int)$f['order_id'],$action,(int)$f['version'],$evidence);crm_notice('lc-flow:'.$f['order_id'].':'.($f['version']+1),'orders',(int)$f['order_id'],'По заказу изменился следующий шаг. Откройте рабочий цикл.');return ['ok'=>true,'id'=>(int)$f['order_id'],'record'=>lc_flow_detail($a,(int)$f['order_id'])];
}
function lc_flow_create(array $a,array $d):array{cc_owner($a);$p=cc_project($a,cc_id($d['project_id']??null),true,true);if(!$p['order_id'])crm_fail(422,'Свяжите проект с заказом.');$o=crm_record('orders',(int)$p['order_id'],true);$old=crm_query('SELECT order_id FROM nd_lc_order_flow WHERE order_id=?',[$o['id']])->fetchColumn();if($old)return ['ok'=>true,'id'=>(int)$old,'record'=>lc_flow_detail($a,(int)$old)];crm_query('INSERT INTO nd_lc_order_flow(order_id,project_id) VALUES (?,?)',[$o['id'],$p['id']]);lc_audit($a,'order',(int)$o['id'],'lifecycle_started',null,['project_id'=>$p['id']]);return ['ok'=>true,'id'=>(int)$o['id'],'record'=>lc_flow_detail($a,(int)$o['id'])];}
function lc_financial_facets(array $f):array{$items=crm_query('SELECT i.* FROM nd_invoices i JOIN nd_lc_schedule_entries s ON s.invoice_id=i.id WHERE s.order_id=? ORDER BY s.position',[$f['order_id']])->fetchAll();$paid=0;$debt=0;$over=0;$refund=0;foreach($items as &$i){$i['balance']=bill_balance($i);$paid+=$i['balance']['net_minor'];$refund+=$i['balance']['refunded_minor'];$debt+=$i['balance']['outstanding_minor'];$over+=max(0,$i['balance']['net_minor']-(int)$i['total_minor']);}unset($i);$state=!$items?'NOT_REQUESTED':($over?'RECONCILIATION':($debt===0?'SETTLED':($paid>0?'PARTIAL':'PENDING')));return ['state'=>$state,'net_minor'=>$paid,'outstanding_minor'=>$debt,'overpayment_minor'=>$over,'refunded_minor'=>$refund,'items'=>$items];}
function lc_payment_gate(array $f,string $gate,?int $stage=null):void{$sql='SELECT i.* FROM nd_invoices i JOIN nd_lc_schedule_entries s ON s.invoice_id=i.id WHERE s.order_id=? AND s.gate=?';$params=[$f['order_id'],$gate];if($stage!==null){$sql.=' AND s.stage_id=?';$params[]=$stage;}$items=crm_query($sql.' FOR UPDATE',$params)->fetchAll();foreach($items as $i)if($i['state']!=='issued'||bill_balance($i)['outstanding_minor']>0)crm_fail(409,'Не подтверждена оплата, предусмотренная подписанным графиком для этого шага.');}
function lc_manifest(array $f,bool $accepted=true):array{$stages=crm_query('SELECT * FROM nd_project_stages WHERE project_id=? ORDER BY position,id',[$f['project_id']])->fetchAll();if(!$stages)crm_fail(409,'Сначала определите этапы и проверяемые результаты.');$out=[];foreach($stages as $stage){$v=crm_query('SELECT * FROM nd_lc_milestone_versions WHERE stage_id=? ORDER BY revision_number DESC LIMIT 1',[$stage['id']])->fetch();if(!$v||$accepted&&$v['state']!=='ACCEPTED')crm_fail(409,'Не все текущие версии этапов приняты клиентом.');$out[]=['stage_id'=>(int)$stage['id'],'title'=>$stage['title'],'version_id'=>(int)$v['id'],'revision_number'=>(int)$v['revision_number'],'checksum'=>$v['checksum'],'evidence'=>json_decode($v['evidence_json'],true)];}return $out;}
function lc_flow_detail(array $a,int $id):array{
 $f=lc_flow($a,$id);$f['order']=crm_record('orders',$id);if($a['type']==='customer'){unset($f['order']['notes']);if(!in_array($f['commercial_state'],['PROPOSAL_SENT','PROPOSAL_ACCEPTED'],true))unset($f['order']['total_amount']);}$f['payment']=lc_financial_facets($f);$f['proposal_hash']=$f['proposal_binding_id']?lc_binding($a,(int)$f['proposal_binding_id'])['generated_hash']:null;$f['document_state']=$f['agreement_binding_id']?'AGREED':'PENDING';$f['obligations']=crm_query('SELECT * FROM nd_lc_obligations WHERE order_id=? ORDER BY kind,id',[$id])->fetchAll();$f['milestones']=crm_query('SELECT v.*,s.title FROM nd_lc_milestone_versions v JOIN nd_project_stages s ON s.id=v.stage_id WHERE v.order_id=? ORDER BY s.position,v.revision_number',[$id])->fetchAll();$f['feedback']=crm_query('SELECT r.*,v.stage_id FROM nd_lc_feedback r JOIN nd_lc_milestone_versions v ON v.id=r.milestone_version_id WHERE v.order_id=? ORDER BY r.id',[$id])->fetchAll();$f['changes']=crm_query('SELECT * FROM nd_lc_scope_changes WHERE order_id=? ORDER BY id',[$id])->fetchAll();$f['decisions']=crm_query('SELECT * FROM nd_lc_business_decisions WHERE order_id=? ORDER BY id',[$id])->fetchAll();$f['audit']=crm_query("SELECT actor_type,actor_id,action,prior_version,evidence_json,created_at FROM nd_lc_audit WHERE entity='order' AND record_id=? ORDER BY id DESC LIMIT 100",[$id])->fetchAll();
 $next=match($f['commercial_state']){'INQUIRY'=>['owner','Примите решение о квалификации заявки.'],'QUALIFIED'=>['owner','Уточните бриф и прикрепите подготовленную версию ТЗ.'],'BRIEF_READY'=>['owner','Проверьте затраты и одобрите точный расчёт.'],'PRICE_APPROVED'=>['owner','Подготовьте и отправьте предложение по одобренному шаблону.'],'PROPOSAL_SENT'=>['customer','Проверьте точное предложение и передайте решение.'],default=>['owner','Оформите и проверьте подписанный договор.']};
 if($f['agreement_binding_id']){$next=['owner','Откройте согласованный график оплаты.'];if($f['payment']['items'])$next=['owner','Проверьте оплату по графику и готовность материалов.'];if($f['delivery_state']==='IN_PRODUCTION')$next=['owner','Выполните этап, запишите тесты и реальную публикацию.'];if($f['delivery_state']==='CLIENT_REVIEW')$next=['customer','Проверьте показанную версию этапа и оставьте консолидированный ответ.'];if($f['acceptance_state']==='REVIEW')$next=['customer','Проверьте итоговый состав результата и передайте решение.'];if($f['acceptance_state']==='ACCEPTED')$next=['owner','Проверьте согласованный расчёт, акт и подготовьте передачу.'];if($f['delivery_state']==='HANDED_OVER')$next=['owner','Проверьте все обязательства, чеки и поддержку перед закрытием.'];}
 if($f['case_state']!=='ACTIVE')$next=['owner',match($f['case_state']){'PAUSED'=>'Согласуйте возобновление работ.','DISPUTED'=>'Разберите спор, сохраняя доступ к истории и чекам.','CLOSED'=>'Заказ закрыт. Поддержка и история сохранены.',default=>'Работы остановлены; расчёты и чеки сохраняют отдельные обязательства.'}];if($a['type']==='customer')foreach($f['audit'] as &$event)unset($event['evidence_json']);unset($event);$f['next_action']=['responsible'=>$next[0],'text'=>$next[1]];return $f;
}
function lc_flow_commercial(array $a,array $f,string $action,array $d):array{
 cc_owner($a);lc_flow_active($f);$reason=cc_text($d,'reason',2000);if(($d['confirm']??false)!==true)crm_fail(422,'Подтвердите решение владельца.');
 if($action==='qualify'){if($f['commercial_state']!=='INQUIRY')crm_fail(409,'Квалификация уже зафиксирована.');return lc_flow_save($a,$f,'qualified',['commercial_state'=>'QUALIFIED'],['reason'=>$reason]);}
 if($action==='brief'){if(!in_array($f['commercial_state'],['QUALIFIED','BRIEF_READY'],true))crm_fail(409,'Сначала квалифицируйте обращение.');$r=cc_revision($a,cc_id($d['revision_id']??null));if((int)$r['document']['project_id']!==(int)$f['project_id']||$r['document']['kind']!=='specification'||$r['status']==='draft'||mb_strlen($r['fields']['requirements']??'')<20||mb_strlen($r['fields']['acceptance']??'')<5)crm_fail(422,'Нужна подготовленная версия ТЗ этого проекта с требованиями и критериями.');return lc_flow_save($a,$f,'brief_ready',['brief_revision_id'=>(int)$r['id'],'commercial_state'=>'BRIEF_READY'],['reason'=>$reason,'checksum'=>$r['checksum']]);}
 if($action==='quote'){if($f['commercial_state']!=='BRIEF_READY')crm_fail(409,'Сначала зафиксируйте готовый бриф.');$q=pricing_detail(cc_id($d['quotation_id']??null));if((int)$q['project_id']!==(int)$f['project_id']||$q['state']!=='APPROVED'||!pricing_fresh($q))crm_fail(409,'Нужен актуальный расчёт с одобрением владельца.');$brief=cc_revision($a,(int)$f['brief_revision_id']);$bound=false;foreach($q['calculation']['scope']['specifications']??[] as $spec)if((int)$spec['id']===(int)$brief['document_id']&&(int)$spec['head_revision']===(int)$brief['revision_number']&&$spec['checksum']===$brief['checksum'])$bound=true;if(!$bound)crm_fail(409,'Расчёт должен включать зафиксированную версию ТЗ.');return lc_flow_save($a,$f,'price_bound',['quotation_id'=>(int)$q['id'],'commercial_state'=>'PRICE_APPROVED'],['reason'=>$reason,'checksum'=>$q['checksum']]);}
 if($action==='proposal'){if($f['commercial_state']!=='PRICE_APPROVED')crm_fail(409,'Сначала одобрите и закрепите цену.');$b=lc_binding($a,cc_id($d['binding_id']??null));$in=json_decode($b['input_snapshot'],true);if((int)$b['order_id']!==(int)$f['order_id']||$b['kind']!=='proposal'||$b['state']!=='SENT'||(int)$in['quotation']['id']!==(int)$f['quotation_id'])crm_fail(422,'Нужно отправленное точное предложение этого заказа и расчёта.');return lc_flow_save($a,$f,'proposal_bound',['proposal_binding_id'=>(int)$b['id'],'commercial_state'=>'PROPOSAL_SENT'],['reason'=>$reason,'checksum'=>$b['generated_hash']]);}
 if($action==='agreement'){if($f['commercial_state']!=='PROPOSAL_ACCEPTED')crm_fail(409,'Сначала требуется коммерческое решение клиента по предложению.');$b=lc_binding($a,cc_id($d['binding_id']??null));if((int)$b['order_id']!==(int)$f['order_id']||$b['kind']!=='agreement'||$b['state']!=='AGREED')crm_fail(422,'Нужен договор этого заказа с проверенной подписанной копией.');$proposal=lc_binding($a,(int)$f['proposal_binding_id']);$pin=json_decode($proposal['input_snapshot'],true);$in=json_decode($b['input_snapshot'],true);foreach(['subject','deliverables','exclusions','acceptance_criteria','milestones','dependencies','price','payment_schedule','revision_rounds','third_party_costs','handover_terms','support_terms'] as $key)if(($pin['fields'][$key]??null)!==($in['fields'][$key]??null))crm_fail(409,'Условия договора отличаются от принятого предложения. Требуется отдельное согласование изменений.');return lc_flow_save($a,$f,'agreement_bound',['agreement_binding_id'=>(int)$b['id']],['reason'=>$reason,'checksum'=>$b['generated_hash']]);}
 crm_fail(404,'Действие не найдено.');
}
function lc_obligation_add(array $a,array $f,array $d):array{cc_owner($a);lc_flow_active($f);$kind=$d['kind']??'';if(!in_array($kind,['MATERIAL','HANDOVER'],true)||!is_bool($d['required']??null))crm_fail(422,'Выберите тип и обязательность пункта.');$title=cc_text($d,'title',190);$details=cc_text($d,'details',4000);if($f['delivery_state']==='HANDED_OVER'||$f['case_state']==='CLOSED')crm_fail(409,'После передачи добавления оформляются отдельно.');crm_query('INSERT INTO nd_lc_obligations(order_id,kind,title,details,required) VALUES (?,?,?,?,?)',[$f['order_id'],$kind,$title,$details,$d['required']?1:0]);$id=(int)db()->lastInsertId();lc_audit($a,'order',(int)$f['order_id'],'obligation_created',(int)$f['version'],['id'=>$id,'kind'=>$kind]);return ['ok'=>true,'id'=>$id];}
function lc_obligation_action(array $a,array $f,int $id,string $action,array $d):array{
 lc_flow_active($f);$r=crm_query('SELECT * FROM nd_lc_obligations WHERE id=? AND order_id=? FOR UPDATE',[$id,$f['order_id']])->fetch();if(!$r)crm_fail(404,'Пункт не найден.');crm_version($d,$r);$reason=cc_text($d,'reason',2000);$file=null;
 if($action==='submit'){if($a['type']==='customer'&&$r['kind']!=='MATERIAL')crm_fail(403,'Пункт передачи заполняет владелец.');if($r['state']==='VERIFIED')crm_fail(409,'Проверенный пункт сохраняется. Оформите отдельное дополнение.');$file=$d['file_id']??null;if($file!==null){$files=cc_files_for($a,(int)$f['project_id'],[cc_id($file)],$r['kind']!=='HANDOVER');if($r['kind']==='HANDOVER'&&$files[0]['visibility']!=='internal')crm_fail(422,'Материалы передачи сначала загрузите с внутренним доступом. Публикация выполняется после проверки графика оплаты.');cc_file_path($files[0]);}$state='SUBMITTED';}
 elseif(in_array($action,['verify','not-applicable'],true)){cc_owner($a);if(($d['confirm']??false)!==true)crm_fail(422,'Подтвердите фактическую проверку пункта.');if($action==='verify'&&$r['state']!=='SUBMITTED')crm_fail(409,'Сначала приложите материал или описание передачи.');$state=$action==='verify'?'VERIFIED':'NOT_APPLICABLE';crm_query('UPDATE nd_lc_obligations SET verified_by=1,verified_at=UTC_TIMESTAMP() WHERE id=?',[$id]);}else crm_fail(404,'Действие не найдено.');
 crm_query('UPDATE nd_lc_obligations SET state=?,file_id=COALESCE(?,file_id),verification_reason=?,version=version+1 WHERE id=?',[$state,$file,$reason,$id]);lc_audit($a,'order',(int)$f['order_id'],'obligation_'.$state,(int)$f['version'],['id'=>$id,'file_id'=>$file,'reason'=>$reason]);return ['ok'=>true,'id'=>$id];
}
function lc_obligations_ready(array $f,string $kind):void{$rows=crm_query("SELECT id FROM nd_lc_obligations WHERE order_id=? AND kind=? AND required=1 AND state NOT IN ('VERIFIED','NOT_APPLICABLE') FOR UPDATE",[$f['order_id'],$kind])->fetchAll();if($rows)crm_fail(409,'Не все обязательные пункты проверены владельцем.');}
function lc_public_url(array $d,string $key,bool $isolated=false):string{$url=cc_text($d,$key,2000);$host=parse_url($url,PHP_URL_HOST);if(filter_var($url,FILTER_VALIDATE_URL)===false||parse_url($url,PHP_URL_SCHEME)!=='https'||!is_string($host)||parse_url($url,PHP_URL_USER)!==null||parse_url($url,PHP_URL_PASS)!==null||$isolated&&in_array(strtolower($host),['neurodelo.pro','www.neurodelo.pro'],true))crm_fail(422,'Нужен HTTPS-адрес без пароля. Клиентский результат размещается отдельно от neurodelo.pro.');$query=[];parse_str((string)parse_url($url,PHP_URL_QUERY),$query);foreach(array_keys($query) as $name)if(preg_match('/token|secret|password|authorization|signature|api.?key/i',(string)$name))crm_fail(422,'Не передавайте секреты и закрытые ссылки доступа в доказательствах публикации.');return $url;}
function lc_milestone_publish(array $a,array $f,array $d):array{
 cc_owner($a);lc_flow_active($f);if(!$f['agreement_binding_id']||!in_array($f['delivery_state'],['IN_PRODUCTION','OWNER_REVIEW','CLIENT_REVIEW'],true))crm_fail(409,'Сначала подтвердите готовность производства по договору.');$stage=cc_id($d['stage_id']??null);if(!crm_query('SELECT id FROM nd_project_stages WHERE id=? AND project_id=?',[$stage,$f['project_id']])->fetchColumn())crm_fail(422,'Выберите этап этого проекта.');lc_payment_gate($f,'milestone',$stage);
 if(crm_query("SELECT id FROM nd_lc_scope_changes WHERE order_id=? AND owner_decision='ACCEPT' AND client_decision='ACCEPT' AND applied_at IS NULL LIMIT 1",[$f['order_id']])->fetchColumn())crm_fail(409,'Сначала оформите и примените принятое изменение объёма.');
 $e=[];foreach(['deliverables','acceptance_criteria','test_results','verification_evidence','owner_review'] as $key)$e[$key]=cc_text($d,$key,6000);foreach(['ci_url','preview_url','deployment_url'] as $key)$e[$key]=lc_public_url($d,$key,$key!=='ci_url');$e['published_revision']=cc_text($d,'published_revision',120);if(!preg_match('/^[A-Za-z0-9][A-Za-z0-9._\/-]{0,119}$/D',$e['published_revision'])||($d['confirm_actual_deployment']??false)!==true)crm_fail(422,'Подтвердите проверку реально опубликованной версии; ветка и зелёный CI не заменяют публикацию.');$e['agreement_hash']=lc_binding($a,(int)$f['agreement_binding_id'])['generated_hash'];$e['evidence_source']='OWNER_ATTESTED';$e['independently_verified_by_application']=false;
 $latest=crm_query('SELECT * FROM nd_lc_milestone_versions WHERE stage_id=? ORDER BY revision_number DESC LIMIT 1 FOR UPDATE',[$stage])->fetch();if($latest&&$latest['state']==='AWAITING_CLIENT')crm_fail(409,'Сначала дождитесь консолидированного ответа по отправленной версии.');$n=$latest?(int)$latest['revision_number']+1:1;$hash=hash('sha256',lc_json(['stage_id'=>$stage,'agreement_id'=>(int)$f['agreement_binding_id'],'revision'=>$n,'evidence'=>$e]));crm_query("INSERT INTO nd_lc_milestone_versions(order_id,stage_id,agreement_binding_id,revision_number,evidence_json,checksum,state,owner_verified_at) VALUES (?,?,?,?,?,?,'AWAITING_CLIENT',UTC_TIMESTAMP())",[$f['order_id'],$stage,$f['agreement_binding_id'],$n,lc_json($e),$hash]);$id=(int)db()->lastInsertId();lc_flow_save($a,$f,'milestone_sent',['delivery_state'=>'CLIENT_REVIEW','acceptance_state'=>'PENDING','final_manifest'=>null,'final_hash'=>null],['milestone_version_id'=>$id,'hash'=>$hash]);bill_emit('lc-milestone:'.$id,'new_deliverable','orders',(int)$f['order_id'],(int)crm_record('orders',(int)$f['order_id'])['customer_id']);return ['ok'=>true,'id'=>$id];
}
function lc_milestone_response(array $a,array $f,int $id,array $d):array{
 if($a['type']!=='customer')crm_fail(403,'Ответ по результату передаёт клиент.');lc_flow_active($f);$v=crm_query('SELECT * FROM nd_lc_milestone_versions WHERE id=? AND order_id=? FOR UPDATE',[$id,$f['order_id']])->fetch();if(!$v)crm_fail(404,'Версия не найдена.');crm_version($d,$v);if($v['state']!=='AWAITING_CLIENT'||($d['checksum']??'')!==$v['checksum'])crm_fail(409,'Ответ возможен только на точную ожидающую версию.');$kind=$d['kind']??'';if(!in_array($kind,['ACCEPT','DEFECT','INCLUDED_REVISION','EXTRA_SCOPE'],true)||($d['confirm']??false)!==true)crm_fail(422,'Выберите вид консолидированного ответа и подтвердите решение.');$text=cc_text($d,'feedback',6000);crm_query('INSERT INTO nd_lc_feedback(milestone_version_id,account_id,kind,feedback,checksum,state) VALUES (?,?,?,?,?,?)',[$id,$a['id'],$kind,$text,$v['checksum'],$kind==='ACCEPT'?'RESOLVED':'OPEN']);$feedback=(int)db()->lastInsertId();crm_query('UPDATE nd_lc_milestone_versions SET state=?,version=version+1 WHERE id=?',[$kind==='ACCEPT'?'ACCEPTED':'CHANGES_REQUESTED',$id]);
 lc_flow_save($a,$f,'milestone_response',['delivery_state'=>$kind==='ACCEPT'?'IN_PRODUCTION':'OWNER_REVIEW'],['milestone_version_id'=>$id,'feedback_id'=>$feedback,'kind'=>$kind,'hash'=>$v['checksum']]);return ['ok'=>true,'id'=>$feedback,'additional_work_charged'=>false];
}
function lc_feedback_resolve(array $a,array $f,int $id,array $d):array{cc_owner($a);lc_flow_active($f);$r=crm_query('SELECT r.*,v.order_id,v.stage_id FROM nd_lc_feedback r JOIN nd_lc_milestone_versions v ON v.id=r.milestone_version_id WHERE r.id=? AND v.order_id=? FOR UPDATE',[$id,$f['order_id']])->fetch();if(!$r||$r['state']!=='OPEN')crm_fail(409,'Открытое замечание не найдено.');crm_version($d,$r);$reason=cc_text($d,'reason',3000);$next=cc_id($d['resolution_version_id']??null);$v=crm_query('SELECT * FROM nd_lc_milestone_versions WHERE id=? AND stage_id=?',[$next,$r['stage_id']])->fetch();if(!$v||$next<=(int)$r['milestone_version_id']||$v['state']!=='ACCEPTED')crm_fail(409,'Укажите новую версию этого этапа, фактически принятую клиентом.');if($r['kind']==='EXTRA_SCOPE'&&!crm_query("SELECT id FROM nd_lc_scope_changes WHERE order_id=? AND owner_decision='ACCEPT' AND client_decision='ACCEPT' AND applied_at IS NOT NULL LIMIT 1",[$f['order_id']])->fetchColumn())crm_fail(409,'Дополнительный объём требует отдельного согласованного и применённого изменения.');crm_query("UPDATE nd_lc_feedback SET state='RESOLVED',resolution=?,resolution_version_id=?,version=version+1 WHERE id=?",[$reason,$next,$id]);lc_audit($a,'order',(int)$f['order_id'],'feedback_resolved',(int)$f['version'],['feedback_id'=>$id,'resolution_version_id'=>$next,'reason'=>$reason]);return ['ok'=>true,'id'=>$id];}
function lc_business_decide(array $a,array $f,string $target,array $d):array{
 if($a['type']!=='customer')crm_fail(403,'Решение передаёт клиент.');lc_flow_active($f);$hash=cc_text($d,'checksum',64);if(!preg_match('/^[a-f0-9]{64}$/D',$hash))crm_fail(422,'Проверьте контрольную сумму версии.');$decision=$d['decision']??'';$reason=cc_text($d,'reason',4000);if(($d['confirm']??false)!==true||!in_array($decision,['ACCEPT','DEFECT','INCLUDED_REVISION','EXTRA_SCOPE','REJECT'],true))crm_fail(422,'Подтвердите выбранное решение по показанной версии.');
 if($target==='PROPOSAL'){if($f['commercial_state']!=='PROPOSAL_SENT'||!$f['proposal_binding_id'])crm_fail(409,'Предложение ещё не отправлено.');$b=lc_binding($a,(int)$f['proposal_binding_id']);if($hash!==$b['generated_hash']||!in_array($decision,['ACCEPT','REJECT'],true))crm_fail(409,'Выберите точное предложение и коммерческое решение.');$values=['commercial_state'=>$decision==='ACCEPT'?'PROPOSAL_ACCEPTED':'PRICE_APPROVED'];}
 elseif($target==='FINAL'){if($f['acceptance_state']!=='REVIEW'||$hash!==$f['final_hash'])crm_fail(409,'Итоговая версия не ожидает ответа.');$values=['acceptance_state'=>$decision==='ACCEPT'?'ACCEPTED':'CHANGES_REQUESTED','delivery_state'=>$decision==='ACCEPT'?'READY_HANDOVER':'OWNER_REVIEW'];}
 elseif($target==='HANDOVER'){if($f['delivery_state']!=='HANDOVER_PREPARED'||$decision!=='ACCEPT'||$hash!==$f['handover_hash'])crm_fail(409,'Передача ещё не подготовлена.');$items=crm_query("SELECT id,title,details,file_id,verification_reason FROM nd_lc_obligations WHERE order_id=? AND kind='HANDOVER' ORDER BY id",[$f['order_id']])->fetchAll();if($hash!==hash('sha256',lc_json($items)))crm_fail(409,'Состав передачи изменился.');lc_obligations_ready($f,'HANDOVER');lc_payment_gate($f,'handover');$values=['delivery_state'=>'HANDED_OVER'];}else crm_fail(404,'Решение не найдено.');
 crm_query('INSERT INTO nd_lc_business_decisions(order_id,target_kind,target_hash,actor_id,decision,reason) VALUES (?,?,?,?,?,?)',[$f['order_id'],$target,$hash,$a['id'],$decision,$reason]);return lc_flow_save($a,$f,'business_'.strtolower($target),$values,['hash'=>$hash,'decision'=>$decision,'reason'=>$reason,'electronic_signature'=>false]);
}
function lc_delivery_action(array $a,array $f,string $action,array $d):array{
 cc_owner($a);lc_flow_active($f);if(($d['confirm']??false)!==true)crm_fail(422,'Подтвердите фактическую проверку этого шага.');$reason=cc_text($d,'reason',3000);
 if($action==='start-production'){if(!$f['agreement_binding_id']||$f['commercial_state']!=='PROPOSAL_ACCEPTED')crm_fail(409,'Сначала нужны принятое предложение и проверенный подписанный договор.');if(!lc_financial_facets($f)['items'])crm_fail(409,'Сначала закрепите реальный график оплаты.');lc_payment_gate($f,'production');lc_obligations_ready($f,'MATERIAL');if(!crm_query('SELECT id FROM nd_lc_obligations WHERE order_id=? AND kind=\'MATERIAL\' LIMIT 1',[$f['order_id']])->fetchColumn())crm_fail(409,'Укажите материалы либо явный проверенный пункт «Материалы не требуются».');crm_query("UPDATE nd_projects SET status='active',version=version+1 WHERE id=?",[$f['project_id']]);crm_query("UPDATE nd_orders SET status='in_progress',version=version+1 WHERE id=?",[$f['order_id']]);return lc_flow_save($a,$f,'production_started',['delivery_state'=>'IN_PRODUCTION'],['reason'=>$reason]);}
 if($action==='request-final'){if($f['acceptance_state']==='REVIEW')crm_fail(409,'Итоговая версия уже ожидает ответа.');$manifest=lc_manifest($f);if(crm_query("SELECT r.id FROM nd_lc_feedback r JOIN nd_lc_milestone_versions v ON v.id=r.milestone_version_id WHERE v.order_id=? AND r.state='OPEN' LIMIT 1",[$f['order_id']])->fetchColumn())crm_fail(409,'Сначала разрешите открытые замечания.');lc_payment_gate($f,'acceptance');$json=lc_json(['agreement_id'=>(int)$f['agreement_binding_id'],'milestones'=>$manifest]);$hash=hash('sha256',$json);if(crm_query("SELECT id FROM nd_lc_business_decisions WHERE order_id=? AND target_kind='FINAL' AND target_hash=?",[$f['order_id'],$hash])->fetchColumn())crm_fail(409,'По этому составу результата уже есть решение. Сначала выполните и проверьте новую версию.');return lc_flow_save($a,$f,'final_requested',['final_manifest'=>$json,'final_hash'=>$hash,'acceptance_state'=>'REVIEW','delivery_state'=>'CLIENT_REVIEW'],['reason'=>$reason,'hash'=>$hash]);}
 if($action==='prepare-handover'){if($f['acceptance_state']!=='ACCEPTED')crm_fail(409,'Сначала требуется явная приёмка итоговой версии клиентом.');lc_payment_gate($f,'handover');lc_obligations_ready($f,'HANDOVER');$items=crm_query("SELECT id,title,details,file_id,verification_reason FROM nd_lc_obligations WHERE order_id=? AND kind='HANDOVER' ORDER BY id",[$f['order_id']])->fetchAll();if(!$items)crm_fail(409,'Сначала подготовьте проверяемый состав передачи.');foreach($items as $item)if($item['file_id']){$file=cc_file($a,(int)$item['file_id'],true);cc_file_path($file);if(crm_query('SELECT id FROM nd_lc_bank_records WHERE evidence_file_id=? LIMIT 1',[$file['id']])->fetchColumn())crm_fail(422,'Банковское доказательство не является материалом передачи.');crm_query("UPDATE nd_cc_files SET visibility='customer',version=version+1 WHERE id=?",[$file['id']]);}return lc_flow_save($a,$f,'handover_prepared',['delivery_state'=>'HANDOVER_PREPARED','handover_hash'=>hash('sha256',lc_json($items))],['reason'=>$reason,'hash'=>hash('sha256',lc_json($items))]);}
 crm_fail(404,'Шаг не найден.');
}
function lc_scope_change(array $a,array $f,int $id,string $action,array $d):array{
 lc_flow_active($f);if($action==='create'){$text=cc_text($d,'request_body',6000);crm_query('INSERT INTO nd_lc_scope_changes(order_id,actor_type,actor_id,request_body) VALUES (?,?,?,?)',[$f['order_id'],$a['type'],$a['id'],$text]);$cid=(int)db()->lastInsertId();lc_audit($a,'order',(int)$f['order_id'],'scope_change_requested',(int)$f['version'],['change_id'=>$cid]);return ['ok'=>true,'id'=>$cid,'price_changed'=>false];}
 $change=crm_query('SELECT * FROM nd_lc_scope_changes WHERE id=? AND order_id=? FOR UPDATE',[$id,$f['order_id']])->fetch();if(!$change)crm_fail(404,'Изменение не найдено.');crm_version($d,$change);$reason=cc_text($d,'reason',3000);if(($d['confirm']??false)!==true)crm_fail(422,'Подтвердите отдельное решение по изменению.');
 if($action==='propose'){cc_owner($a);if($change['proposal_json']!==null||$change['client_decision']!==null)crm_fail(409,'Предложенная редакция неизменяема. Оформите отдельное изменение.');$q=pricing_detail(cc_id($d['quotation_id']??null));if((int)$q['project_id']!==(int)$f['project_id']||$q['state']!=='APPROVED'||!pricing_fresh($q))crm_fail(409,'Нужен актуальный одобренный расчёт изменённого полного объёма.');$old=bill_minor(crm_record('orders',(int)$f['order_id'])['total_amount']);$proposal=['request'=>$change['request_body'],'revised_scope'=>cc_text($d,'revised_scope',10000),'schedule_effect'=>cc_text($d,'schedule_effect',4000),'old_total_minor'=>$old,'new_total_minor'=>(int)$q['calculation']['selling_minor'],'price_effect_minor'=>(int)$q['calculation']['selling_minor']-$old,'quotation_id'=>(int)$q['id'],'quotation_hash'=>$q['checksum'],'reason'=>$reason];$hash=hash('sha256',lc_json($proposal));crm_query("UPDATE nd_lc_scope_changes SET proposal_json=?,checksum=?,owner_decision='ACCEPT',decision_reason=?,version=version+1 WHERE id=?",[lc_json($proposal),$hash,$reason,$id]);}
 elseif($action==='decide'){if($a['type']!=='customer')crm_fail(403,'Клиент передаёт своё решение отдельно от владельца.');if($change['proposal_json']===null||$change['client_decision']!==null||($d['checksum']??'')!==$change['checksum']||!in_array($d['decision']??'',['ACCEPT','REJECT'],true))crm_fail(409,'Выберите точную предложенную редакцию, по которой ещё нет решения.');crm_query('UPDATE nd_lc_scope_changes SET client_decision=?,version=version+1 WHERE id=?',[$d['decision'],$id]);}
 elseif($action==='reject'){cc_owner($a);if($change['client_decision']==='ACCEPT'||$change['applied_at']!==null)crm_fail(409,'Принятое изменение нельзя молча отменить. Нужно отдельное согласование.');crm_query("UPDATE nd_lc_scope_changes SET owner_decision='REJECT',decision_reason=?,version=version+1 WHERE id=?",[$reason,$id]);}else crm_fail(404,'Действие не найдено.');
 lc_audit($a,'order',(int)$f['order_id'],'scope_change_'.$action,(int)$f['version'],['change_id'=>$id,'reason'=>$reason,'checksum'=>$change['checksum'],'decision'=>$d['decision']??null]);return ['ok'=>true,'id'=>$id,'price_changed'=>false,'requires_signed_change_document'=>true];
}
function lc_case_action(array $a,array $f,string $action,array $d):array{
 cc_owner($a);$reason=cc_text($d,'reason',4000);if(($d['confirm']??false)!==true)crm_fail(422,'Подтвердите решение и его основание.');$target=match($action){'pause'=>'PAUSED','dispute'=>'DISPUTED','cancel'=>'CANCELLED','decline'=>'DECLINED','resume'=>'ACTIVE',default=>''};if($target===''||in_array($f['case_state'],['CLOSED','CANCELLED','DECLINED'],true))crm_fail(409,'Текущее состояние не допускает этот переход.');if($action==='resume'&&!in_array($f['case_state'],['PAUSED','DISPUTED'],true)||$action!=='resume'&&$f['case_state']!=='ACTIVE')crm_fail(409,'Проверьте текущее состояние заказа.');if($action==='decline'&&!in_array($f['commercial_state'],['INQUIRY','QUALIFIED'],true))crm_fail(409,'После коммерческого согласования используйте прекращение или спор с отдельной сверкой обязательств.');return lc_flow_save($a,$f,'case_'.$action,['case_state'=>$target],['reason'=>$reason,'financial_obligations_erased'=>false]);
}
function lc_support_record(array $a,array $f,array $d):array{cc_owner($a);lc_flow_active($f);if(in_array($f['delivery_state'],['HANDOVER_PREPARED','HANDED_OVER'],true)||($d['confirm']??false)!==true)crm_fail(409,'Поддержка фиксируется по согласованным условиям до передачи результата.');$terms=cc_text($d,'support_terms',5000);$start=$d['support_start']??null;$end=$d['support_end']??null;if($start!==null||$end!==null){$start=pricing_date($d,'support_start');$end=pricing_date($d,'support_end');if($end<$start)crm_fail(422,'Окончание поддержки раньше начала.');}return lc_flow_save($a,$f,'support_recorded',['support_terms'=>$terms,'support_start'=>$start,'support_end'=>$end],['reason'=>cc_text($d,'reason',2000),'contract_reviewed'=>true]);}
function lc_flow_dispatch(array $a,string $route,string $method,?array $data=null):never{
 if(!lc_flow_installed())crm_fail(503,'Рабочий цикл ещё не подготовлен.');
 if($method==='GET'){
  if($route==='orders'){$params=[];$where='';if($a['type']==='customer'){$where=' WHERE o.customer_id=?';$params[]=$a['customer_id'];}$items=crm_query('SELECT f.order_id,f.project_id,f.commercial_state,f.delivery_state,f.acceptance_state,f.case_state,f.version,o.title FROM nd_lc_order_flow f JOIN nd_orders o ON o.id=f.order_id'.$where.' ORDER BY f.order_id DESC LIMIT 100',$params)->fetchAll();json_response(['ok'=>true,'items'=>$items]);}
  if(preg_match('~^orders/([1-9][0-9]*)$~D',$route,$m))json_response(['ok'=>true,'record'=>lc_flow_detail($a,(int)$m[1])]);
  if(preg_match('~^orders/([1-9][0-9]*)/codex-task$~D',$route,$m)){cc_owner($a);$f=lc_flow($a,(int)$m[1]);if(!$f['agreement_binding_id'])crm_fail(409,'Сначала согласуйте подписанный объём.');$b=lc_binding($a,(int)$f['agreement_binding_id']);$input=json_decode($b['input_snapshot'],true);$safe=['deliverables'=>$input['fields']['deliverables'],'exclusions'=>$input['fields']['exclusions'],'acceptance_criteria'=>$input['fields']['acceptance_criteria'],'milestones'=>$input['fields']['milestones'],'dependencies'=>$input['fields']['dependencies']];$task="Implement the approved client scope below in an isolated client repository and preview environment. Do not deploy the client application over neurodelo.pro. Preserve existing architecture, data, credentials and protections. This application cannot invoke Codex: the owner copies this task manually. Do not include personal details or secrets in your output. Complete IMPLEMENT -> TEST -> PR -> INTEGRATE -> ISOLATED DEPLOY -> VERIFY. Record actual CI URLs, deployed revision and verification evidence; a pushed branch/green CI alone is not publication. Do not assume paid APIs or acquiring. Return consolidated deliverables and limitations.\nApproved input SHA256: ".$b['generated_hash']."\n".lc_json($safe);json_response(['ok'=>true,'task'=>$task,'external_execution_started'=>false]);}
 }
 if($method==='POST'){$d=$data??input();$result=cc_mutation($a,'flow/'.$route,$d,function()use($a,$route,$d){if($route==='orders')return lc_flow_create($a,$d);if(preg_match('~^orders/([1-9][0-9]*)(?:/(.*))?$~D',$route,$m)){$id=(int)$m[1];crm_record('orders',$id,true);$f=lc_flow($a,$id,true);$action=$m[2]??'';if(str_starts_with($action,'obligations/')){if(preg_match('~^obligations/([1-9][0-9]*)/(submit|verify|not-applicable)$~D',$action,$x))return lc_obligation_action($a,$f,(int)$x[1],$x[2],$d);}
   if(preg_match('~^milestones/([1-9][0-9]*)/respond$~D',$action,$x))return lc_milestone_response($a,$f,(int)$x[1],$d);
   if(preg_match('~^feedback/([1-9][0-9]*)/resolve$~D',$action,$x))return lc_feedback_resolve($a,$f,(int)$x[1],$d);
   if(preg_match('~^changes/([1-9][0-9]*)/(propose|decide|reject)$~D',$action,$x))return lc_scope_change($a,$f,(int)$x[1],$x[2],$d);
   crm_version($d,$f);if(in_array($action,['qualify','brief','quote','proposal','agreement'],true))return lc_flow_commercial($a,$f,$action,$d);
   if($action==='obligations')return lc_obligation_add($a,$f,$d);if($action==='milestones')return lc_milestone_publish($a,$f,$d);if($action==='changes')return lc_scope_change($a,$f,0,'create',$d);if($action==='support')return lc_support_record($a,$f,$d);
   if(in_array($action,['start-production','request-final','prepare-handover'],true))return lc_delivery_action($a,$f,$action,$d);
   if(in_array($action,['pause','dispute','cancel','decline','resume'],true))return lc_case_action($a,$f,$action,$d);
   if(preg_match('~^decision/(PROPOSAL|FINAL|HANDOVER)$~D',$action,$x))return lc_business_decide($a,$f,$x[1],$d);
  }crm_fail(404,'Действие не найдено.');});json_response($result);}
 crm_fail(404,'Раздел не найден.');
}
